def AlphaNum_NumAlpha(input_string):
    alphabetnums = {chr(i + 96): str(i) for i in range(1, 27)}
    numalphabet = {str(i): chr(i + 96) for i in range(1, 27)}
    result = []
    i = 0
    while i < len(input_string):
        if input_string[i].isdigit():
            j = i
            while j < len(input_string) and input_string[j].isdigit():
                j += 1
            result.append(numanphabet[input_string[i:j]])
            i = j
        else:
            result.append(alphabetnums[input_string[i]])
            i += 1
    return ''.join(result)
